import sys
from collections import deque

def main():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()
    m = len(s)
    if m == 0:
        print(0)
        return
    # Compute failure function for KMP
    fail = [0] * m
    j = 0
    for i in range(1, m):
        while j > 0 and s[i] != s[j]:
            j = fail[j-1]
        if s[i] == s[j]:
            j += 1
            fail[i] = j
        else:
            fail[i] = 0
    # Build transition table for automaton
    # trans[k][c] = next state when in state k and read character c (0 or 1)
    trans = [[0]*2 for _ in range(m+1)]
    for k in range(m+1):
        for c in 0,1:
            if k < m and s[k] == str(c):
                trans[k][c] = k+1
            else:
                if k == 0:
                    trans[k][c] = 0
                else:
                    trans[k][c] = trans[fail[k-1]][c]
    # DP[i][k] = number of strings of length i, ending in state k, not having reached m yet
    # We need to track all possible states, but since we want to avoid reaching m, we can cap at m
    # Initialize DP
    dp = [0]*(m+1)
    dp[0] = 1
    for i in range(n):
        new_dp = [0]*(m+1)
        for k in range(m+1):
            if dp[k] == 0:
                continue
            for c in 0,1:
                nk = trans[k][c]
                if nk < m:
                    new_dp[nk] += dp[k]
                # else: reached m, which we don't count
        dp = new_dp
    # Total valid strings that do NOT contain s as substring
    total_not = sum(dp)
    # Total possible strings
    total = 2**n
    # Answer is total - total_not
    print(total - total_not)

if __name__ == "__main__":
    main()
